CREATE TABLE IF NOT EXISTS review_source_connections (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,source TEXT NOT NULL,account_label TEXT NOT NULL,external_property_id TEXT,connection_status TEXT NOT NULL,last_received_at TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(organization_id,source,account_label));
CREATE TABLE IF NOT EXISTS guest_review_events (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,source TEXT NOT NULL,source_account TEXT NOT NULL,external_id TEXT NOT NULL,guest_name TEXT NOT NULL,rating REAL,review_title TEXT,review_text TEXT NOT NULL,stay_date TEXT,received_at TEXT NOT NULL,sentiment TEXT NOT NULL,urgency TEXT NOT NULL,themes_json TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(organization_id,source,source_account,external_id));
CREATE INDEX IF NOT EXISTS guest_review_events_queue_idx ON guest_review_events(organization_id,sentiment,received_at);
CREATE TABLE IF NOT EXISTS review_response_drafts (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,review_id TEXT NOT NULL UNIQUE,response_text TEXT NOT NULL,response_tone TEXT NOT NULL,model_label TEXT NOT NULL,status TEXT NOT NULL,approved_by TEXT,approved_at TEXT,posted_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS review_recovery_cases (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,review_id TEXT NOT NULL UNIQUE,priority TEXT NOT NULL,department TEXT NOT NULL,summary TEXT NOT NULL,status TEXT NOT NULL,owner_email TEXT,resolved_at TEXT,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS review_recovery_queue_idx ON review_recovery_cases(organization_id,status,priority);
CREATE TABLE IF NOT EXISTS distribution_reservation_records (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,source TEXT NOT NULL,external_id TEXT NOT NULL,confirmation_number TEXT NOT NULL,guest_name TEXT NOT NULL,arrival_date TEXT NOT NULL,departure_date TEXT NOT NULL,room_type TEXT NOT NULL,status TEXT NOT NULL,gross_amount REAL NOT NULL DEFAULT 0,commission_amount REAL NOT NULL DEFAULT 0,currency TEXT NOT NULL DEFAULT 'USD',source_file TEXT NOT NULL,imported_by TEXT NOT NULL,imported_at TEXT NOT NULL,UNIQUE(organization_id,source,external_id));
CREATE INDEX IF NOT EXISTS distribution_reservation_stay_idx ON distribution_reservation_records(organization_id,arrival_date,departure_date);
CREATE TABLE IF NOT EXISTS ota_reconciliation_runs (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,period_start TEXT NOT NULL,period_end TEXT NOT NULL,pms_count INTEGER NOT NULL,ota_count INTEGER NOT NULL,matched_count INTEGER NOT NULL,exception_count INTEGER NOT NULL,gross_amount REAL NOT NULL,commission_amount REAL NOT NULL,net_amount REAL NOT NULL,status TEXT NOT NULL,run_by TEXT NOT NULL,run_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ota_reconciliation_exceptions (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,run_id TEXT NOT NULL,exception_type TEXT NOT NULL,severity TEXT NOT NULL,source TEXT NOT NULL,external_id TEXT,confirmation_number TEXT,summary TEXT NOT NULL,detail_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'OPEN',assigned_to TEXT,resolution_note TEXT,created_at TEXT NOT NULL,resolved_at TEXT,resolved_by TEXT);
CREATE INDEX IF NOT EXISTS ota_exception_queue_idx ON ota_reconciliation_exceptions(organization_id,status,severity);
CREATE TABLE IF NOT EXISTS website_factory_projects (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_asset_id TEXT NOT NULL,name TEXT NOT NULL,slug TEXT NOT NULL,theme TEXT NOT NULL,status TEXT NOT NULL,content_json TEXT NOT NULL,seo_json TEXT NOT NULL,missing_fields_json TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,published_at TEXT,UNIQUE(organization_id,slug));
CREATE TABLE IF NOT EXISTS website_factory_audit (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,project_id TEXT NOT NULL,actor_email TEXT NOT NULL,event_type TEXT NOT NULL,detail_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS website_factory_audit_idx ON website_factory_audit(organization_id,project_id,created_at);
